    );
    const newPos = (maxRes.rows[0].maxpos || 0) + 1;

    // Insert the card
    const insertRes = await db.query(
      `INSERT INTO cards (column_id, text, position) VALUES ($1, $2, $3) RETURNING id, column_id, text, position, created_at`,
      [columnId, text, newPos]
    );

