            position: r.position
          }))
        });
      }

      res.write(`event: board-initial\ndata: ${JSON.stringify(result)}\n\n`);
    } catch (err) {
      console.error('SSE initial state error:', err);
    }
  })();

  subscribers.add(res);

  req.on('close', () => {
    subscribers.delete(res);
  });
});

// ─── Start Server ──────────────────────────────────────────────
app.listen(PORT, () => {
  console.log(`Kanban board server running on http://localhost:${PORT}`);
});
