      // Sort by position
      column.cards.sort((a, b) => a.position - b.position);
      renderBoard();
    }
  });

  eventSource.addEventListener('card-moved', (e) => {
    const card = JSON.parse(e.data);
    reconcileWithServer(card.id, card);
