function getCardBelowCursor(listEl, y) {
  const cards = [...listEl.querySelectorAll('.card:not(.dragging)')];

  for (const card of cards) {
    const rect = card.getBoundingClientRect();
    if (y < rect.top + rect.height / 2) {
