  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, sans-serif;
  background: #0079bf;
  min-height: 100vh;
  padding: 20px;
}

#app h1 {
  color: white;
  text-align: center;
  margin-bottom: 24px;
  font-size: 28px;
  font-weight: 700;
}

#board {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding-bottom: 20px;
  align-items: flex-start;
}

.column {
  background: #ebecf0;
  border-radius: 8px;
  min-width: 280px;
  max-width: 280px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  max-height: calc(100vh - 120px);
}

