function handleDragEnd(e) {
  e.target.classList.remove('dragging');
  if (dragIndicator && dragIndicator.parentNode) {
    dragIndicator.parentNode.removeChild(dragIndicator);
  }
  draggedCardId = null;
  draggedFromColumnId = null;

