    const rect = card.getBoundingClientRect();
    if (y < rect.top + rect.height / 2) {
      return card;
    }
  }

  // If no card found above, check after the last one
  if (cards.length > 0) {
    const lastCard = cards[cards.length - 1];
    const lastRect = lastCard.getBoundingClientRect();
