}

// ─── Reconciliation ────────────────────────────────────────────
function reconcileWithServer(cardId, canonicalCard) {
  // Update the card in our state
  for (const col of boardState) {
    const idx = col.cards.findIndex(c => c.id === cardId);
    if (idx !== -1) {
