    listEl.insertBefore(dragIndicator, afterCard);
  } else {
    listEl.appendChild(dragIndicator);
  }
}

function removeIndicator() {
  if (dragIndicator && dragIndicator.parentNode) {
    dragIndicator.parentNode.removeChild(dragIndicator);
  }
