let eventSource = null;

function connectSSE() {
  if (eventSource) {
    eventSource.close();
  }

  eventSource = new EventSource(`${API_BASE}/stream`);

  eventSource.addEventListener('board-initial', (e) => {
    const data = JSON.parse(e.data);
    reconcileFullBoard(data);
  });

