      // Sort by position
      column.cards.sort((a, b) => a.position - b.position);
      renderBoard();
    }
  });

  eventSource.onerror = (err) => {
    console.error('SSE connection error:', err);
    // Reconnect after a delay
    setTimeout(() => connectSSE(), 3000);
  };
}

// ─── Initialize ────────────────────────────────────────────────
async function init() {
  await loadBoard();
  connectSSE();
}

