    } catch (err) {
      console.error('SSE initial state error:', err);
    }
  })();

  subscribers.add(res);

  req.on('close', () => {
    subscribers.delete(res);
  });
});

// ─── Start Server ──────────────────────────────────────────────
app.listen(PORT, () => {
